import {
  PlaneGeometry,
  Mesh,
  MeshBasicNodeMaterial,
} from 'three/webgpu';

export default function createNode(config, ctx) {
  // Load the atlas texture using the cached loader
  const texture = ctx.textureLoader.load(config.imageUrl);

  // Apply atlas region cropping (UV offset/repeat)
  if (config.atlasRegion) {
    const { x, y, width, height } = config.atlasRegion;
    const img = texture.image;
    if (img) {
      // Assumes texture coordinates (0,0) at bottom-left; adjust for WebGL top-left origin
      texture.offset.set(x / img.width, 1 - (y + height) / img.height);
      texture.repeat.set(width / img.width, height / img.height);
    }
  }

  // Plane geometry (size 1,1 – scale will be applied via config.sceneScale)
  const geometry = new PlaneGeometry(1, 1);

  // Static plane with basic material – no lighting needed
  const material = new MeshBasicNodeMaterial({
    map: texture,
    color: config.colors?.paper || 0xe8ecf2,
    transparent: true,
  });

  const mesh = new Mesh(geometry, material);

  // Placement from config
  if (config.scenePosition) mesh.position.copy(config.scenePosition);
  if (config.quaternion) {
    mesh.quaternion.copy(config.quaternion);
  } else if (config.rotation) {
    mesh.rotation.set(config.rotation.x, config.rotation.y, config.rotation.z);
  }
  if (config.sceneScale) mesh.scale.copy(config.sceneScale);

  // Resources disposal
  mesh.userData.cleanup = () => {
    geometry.dispose();
    material.dispose();
    texture.dispose();
  };

  // No event handlers needed for this static element
  mesh.userData.handlers = {};

  return mesh;
}
